"""SG-22: the import pipeline against messy synthetic files (fixtures/messy, generated by
`sg data synth-messy --seed 7`). Each file's expected.json was built with the data, not by
running the pipeline."""

from __future__ import annotations

import datetime as dt
import json
import logging
import zipfile
from pathlib import Path
from typing import Any

import pytest

from sg_data.imports import run
from sg_data.imports.commit import InMemoryBackend, commit

FIXTURES = Path(__file__).parent / "fixtures" / "messy"
EXPECTED = sorted(FIXTURES.glob("*.expected.json"))
DEPT = "00000000-0000-4000-8000-000000000003"
MIN_FILES = 12
OVERALL_ACCURACY = 0.9


def load(path: Path) -> dict[str, Any]:
    out: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))
    return out


def run_case(exp: dict[str, Any]) -> Any:
    opts = dict(exp["options"])
    if "week_start" in opts:
        opts["week_start"] = dt.date.fromisoformat(opts["week_start"])
    return run((FIXTURES / exp["file"]).read_bytes(), exp["file"], **opts)


def mapping_hits(exp: dict[str, Any], res: Any) -> tuple[int, int]:
    got = {m.column: m.field for m in res.mapping}
    want = exp["mapping"]
    return sum(got.get(c) == f for c, f in want.items()), len(want)


def test_enough_fixtures() -> None:
    assert len(EXPECTED) >= MIN_FILES
    for exp in EXPECTED:
        assert (FIXTURES / load(exp)["file"]).exists()


def _content(path: Path) -> object:
    """CSV bytes, or each workbook entry uncompressed (zlib output differs across builds)."""
    if path.suffix != ".xlsx":
        return path.read_bytes()
    with zipfile.ZipFile(path) as z:
        return {n: z.read(n) for n in sorted(z.namelist())}


def test_generator_is_deterministic(tmp_path: Path) -> None:
    from sg_data.synth_messy import generate

    generate(tmp_path, seed=7)
    for exp in EXPECTED:
        name = load(exp)["file"]
        assert _content(tmp_path / name) == _content(FIXTURES / name), name
        assert (tmp_path / exp.name).read_text(encoding="utf-8") == exp.read_text(encoding="utf-8")


@pytest.mark.parametrize("path", EXPECTED, ids=lambda p: p.name.removesuffix(".expected.json"))
def test_fixture(path: Path, caplog: pytest.LogCaptureFixture) -> None:
    caplog.set_level(logging.DEBUG)
    exp = load(path)
    res = run_case(exp)

    hits, total = mapping_hits(exp, res)
    if exp["kind"] == "exact":
        assert hits == total, {m.column: m.field for m in res.mapping}

    assert sorted(res.dropped_columns) == sorted(exp["dropped_columns"])
    assert res.valid_rows == exp["valid_rows"]
    assert sorted({e["row"] for e in res.errors}) == sorted(exp["error_rows"])
    for want in exp["rows"]:
        day = dt.date.fromisoformat(want["date"])
        got = res.valid[res.valid["date"] == day]
        assert len(got) == 1, want
        for col, value in want.items():
            if col != "date":
                assert got.iloc[0][col] == pytest.approx(value), (want["date"], col)

    # PHI: the flagged cells match (and each expected entity type is among those found).
    found: dict[tuple[str, int], set[str]] = {}
    for f in res.phi_findings:
        if f["row"] is not None:
            found.setdefault((f["column"], f["row"]), set()).add(f["entity_type"])
    expected_cells = {(c["column"], c["row"]): c["entity_type"] for c in exp["phi_cells"]}
    assert set(found) == set(expected_cells)
    for cell, entity in expected_cells.items():
        assert entity in found[cell]

    # No fake identifier survives anywhere: committed rows, reports, logs.
    backend = InMemoryBackend()
    commit(
        backend,
        res.valid,
        department_id=DEPT,
        settings={},
        import_job_id="job",
        content_hash=res.content_hash,
        filename=exp["file"],
    )
    stored = json.dumps(
        [list(backend.plans.values()), list(backend.actuals.values()), backend.datasets],
        default=str,
    )
    report = json.dumps(res.report(), default=str)
    for secret in exp["fake_strings"]:
        assert secret not in stored
        assert secret not in report
        assert secret not in caplog.text


def test_mapping_accuracy_overall() -> None:
    hits = total = 0
    for path in EXPECTED:
        exp = load(path)
        h, t = mapping_hits(exp, run_case(exp))
        hits, total = hits + h, total + t
    assert hits / total >= OVERALL_ACCURACY, f"{hits}/{total}"
